-- ================================================================
-- 10. تحديث الأقساط المتأخرة
-- ================================================================
UPDATE "Installments"
SET "Status" = 'Overdue'
WHERE "Status" = 'Pending'
  AND "DueDate" < NOW()
  AND "PaidAmount" = 0;

-- ================================================================
-- 11. إحصاء النتائج
-- ================================================================
SELECT
  (SELECT COUNT(*) FROM "Vehicles")          AS total_vehicles,
  (SELECT COUNT(*) FROM "Vehicles" WHERE "Status"='Available') AS available,
  (SELECT COUNT(*) FROM "Vehicles" WHERE "Status"='Sold')      AS sold,
  (SELECT COUNT(*) FROM "Customers")         AS customers,
  (SELECT COUNT(*) FROM "Suppliers")         AS suppliers,
  (SELECT COUNT(*) FROM "SalesContracts")    AS sales,
  (SELECT COUNT(*) FROM "Purchases")         AS purchases,
  (SELECT COUNT(*) FROM "InstallmentPlans")  AS plans,
  (SELECT COUNT(*) FROM "Installments")      AS installment_rows,
  (SELECT COUNT(*) FROM "Installments" WHERE "Status"='Overdue') AS overdue,
  (SELECT COUNT(*) FROM "Payments")          AS payments;
